"""Audio ops and the final loudness pass. Clips and tones are generated by ffmpeg (lavfi)."""

import re

import pytest

from src.studio import ffmpeg, recipe
from src.studio.recipe import FitVertical, Music, MuteOriginal, Recipe, VoiceOver, render
from tests.test_studio_ffmpeg import H264, needs_ffmpeg

SMALL = "320x568"


def make_clip(path, *, duration=2, tone=440, gain_db=0.0, audio=True):
    args = ["-f", "lavfi", "-i", f"testsrc2=size={SMALL}:rate=30:duration={duration}"]
    if audio:
        args += ["-f", "lavfi", "-i", f"sine=frequency={tone}:duration={duration}",
                 "-af", f"volume={gain_db}dB", "-c:a", "aac", "-shortest"]
    ffmpeg.run([*args, *H264, path], timeout_s=60)
    return path


def make_tone(path, *, duration, tone):
    ffmpeg.run(["-f", "lavfi", "-i", f"sine=frequency={tone}:duration={duration}",
                "-c:a", "aac", path], timeout_s=60)
    return path


def _log(tmp_path, args):
    log = tmp_path / "measure.log"
    ffmpeg.run(args, timeout_s=60, log_path=log)
    return log.read_text(encoding="utf-8")


def integrated_lufs(tmp_path, path):
    text = _log(tmp_path, ["-i", path, "-map", "0:a:0", "-af", "ebur128", "-f", "null", "-"])
    return float(re.findall(r"I:\s+(-?[\d.]+) LUFS", text)[-1])


def mean_db(tmp_path, path, start, end, band=None):
    """Mean volume of [start, end) seconds, optionally only around `band` Hz."""
    chain = f"atrim={start}:{end}"
    if band:
        chain += f",bandpass=f={band}:width_type=q:w=8"
    text = _log(tmp_path, ["-i", path, "-map", "0:a:0", "-af", f"{chain},volumedetect",
                           "-f", "null", "-"])
    value = re.findall(r"mean_volume: (-?[\d.]+|-inf) dB", text)[-1]
    return float(value)


def video_md5(tmp_path, path):
    out = tmp_path / f"{path.stem}.md5"
    ffmpeg.run(["-i", path, "-map", "0:v:0", "-c", "copy", "-f", "md5", out], timeout_s=60)
    return out.read_text().strip()


def go(tmp_path, ops, inputs):
    return render(Recipe(ops=ops), inputs, tmp_path / "out.mp4", timeout_s=120,
                  preset="ultrafast")


def test_audio_ops_registered_and_round_trip():
    assert {"mute_original", "voice_over", "music"} <= set(recipe.OPS)
    data = {"version": 1, "ops": [{"op": "voice_over", "input": "voice", "gain_db": 0.0,
                                   "duck_db": -12.0},
                                  {"op": "music", "input": "music", "level_db": -20.0,
                                   "loop": True},
                                  {"op": "mute_original"}]}
    assert Recipe.model_validate(data).model_dump() == data


def test_missing_named_input_is_a_clear_error(tmp_path):
    with pytest.raises(ValueError, match="needs input.*voice"):
        render(Recipe(ops=[VoiceOver()]), {"source": tmp_path / "in.mp4"}, tmp_path / "o.mp4")
    with pytest.raises(ValueError, match="needs input.*bed"):
        render(Recipe(ops=[Music(input="bed")]), {"source": tmp_path / "in.mp4"},
               tmp_path / "o.mp4")


@needs_ffmpeg
@pytest.mark.parametrize("gain_db", [-30.0, 17.0])  # quiet and loud inputs
def test_every_render_is_normalised_to_target(tmp_path, gain_db):
    src = make_clip(tmp_path / "in.mp4", gain_db=gain_db)
    assert abs(integrated_lufs(tmp_path, src) - recipe.LOUDNESS_I) > 5
    out = go(tmp_path, [FitVertical()], {"source": src})
    assert integrated_lufs(tmp_path, tmp_path / "out.mp4") == pytest.approx(
        recipe.LOUDNESS_I, abs=1.0)
    assert out.duration == pytest.approx(2.0, abs=0.1)


@needs_ffmpeg
def test_mute_original_keeps_length_and_copies_video(tmp_path):
    src = make_clip(tmp_path / "in.mp4")
    before = ffmpeg.probe(src)
    out = go(tmp_path, [MuteOriginal()], {"source": src})
    assert mean_db(tmp_path, tmp_path / "out.mp4", 0, 2) < -80
    assert out.duration == pytest.approx(before.duration, abs=0.05)
    assert (out.video_codec, out.width, out.height) == ("h264", 320, 568)
    assert out.audio_codec == "aac" and out.sample_rate == 48000
    assert video_md5(tmp_path, tmp_path / "out.mp4") == video_md5(tmp_path, src)


@needs_ffmpeg
@pytest.mark.parametrize("voice_s", [1, 4])  # shorter and longer than the video
def test_voice_over_ducks_the_original(tmp_path, voice_s):
    src = make_clip(tmp_path / "in.mp4", duration=3, tone=440)
    voice = make_tone(tmp_path / "voice.m4a", duration=voice_s, tone=1500)
    out = go(tmp_path, [VoiceOver(duck_db=-12)], {"source": src, "voice": voice})
    path = tmp_path / "out.mp4"
    assert out.duration == pytest.approx(3.0, abs=0.1)
    assert video_md5(tmp_path, path) == video_md5(tmp_path, src)
    voice_on = mean_db(tmp_path, path, 0.3, 0.8, band=1500)
    under = mean_db(tmp_path, path, 0.3, 0.8, band=440)
    if voice_s == 1:
        alone = mean_db(tmp_path, path, 2.0, 2.8, band=440)
        assert under < alone - 8  # ~12 dB duck while the voice plays
        assert mean_db(tmp_path, path, 2.0, 2.8, band=1500) < voice_on - 20  # voice ended
    else:
        assert mean_db(tmp_path, path, 2.0, 2.8, band=1500) == pytest.approx(voice_on, abs=2)
    assert voice_on > under + 6


@needs_ffmpeg
@pytest.mark.parametrize("loop", [True, False])
def test_music_loops_to_video_length(tmp_path, loop):
    src = make_clip(tmp_path / "in.mp4", duration=2, audio=False)
    music = make_tone(tmp_path / "music.m4a", duration=0.5, tone=660)
    out = go(tmp_path, [Music(loop=loop)], {"source": src, "music": music})
    path = tmp_path / "out.mp4"
    assert out.duration == pytest.approx(2.0, abs=0.1)
    assert video_md5(tmp_path, path) == video_md5(tmp_path, src)
    start = mean_db(tmp_path, path, 0.1, 0.4)
    late = mean_db(tmp_path, path, 1.6, 1.9)
    if loop:
        assert late == pytest.approx(start, abs=2)
    else:
        assert late < start - 40
